WITH session_stats AS (SELECT session_id, MAX(event_time) AS last_event_time, ROUND((100 * SUM(CASE WHEN page = '/product' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_product FROM web_events WHERE event_type IN ('click', 'search', 'purchase') GROUP BY session_id) SELECT s.id, s.country, s.customer_id, ss.last_event_time, ss.pct_product FROM sessions s INNER JOIN session_stats ss ON s.id = ss.session_id WHERE ss.pct_product >= 75
